entries[23486] = { ["name"] = "Dimensionszerfetzer: Ewige Warte", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilbarren (10), Echtsilberumwandler , Herz des Feuers (4), Sternrubin (2), Die Große\nBeruf:\nIngenieurskunst (260)\nSpezialisierung:\nGobliningenieurskunst\nZone:\nWinterquell\nNSC:\nZap Weitschleuder\n\nDimensionszerfetzer: Ewige Warte\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Zerreißt die Dimensionsschranken, um Euch zur Ewigen Warte in Winterquell zu transportieren. Manchmal können dabei zwar technische Probleme auftreten, aber das ist ja das Spannende an der Gobliningenieurskunst! (4 Std. Abklingzeit)\nBenötigt Klassische Ingenieurskunst\n(260)\nBenötigt Gobliningenieur" }
