entries[23489] = { ["name"] = "Extrem sicherer Transporter: Gadgetzan", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilbarren (12), Echtsilberumwandler (2), Erdenkern (4), Kugel des Wassers (2), Aquamarin (4), Veredelter Mithrilzylinder\nBeruf:\nIngenieurskunst (260)\nSpezialisierung:\nGnomeningenieurskunst\nZone:\nTanaris\nNSC:\nJhordy Lapforge\n\nExtrem sicherer Transporter: Gadgetzan\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Transportiert Euch sicher nach Gadgetzan in Tanaris! Die Betonung liegt auf sicher! Jawohl, nichts kann Euch jemals passieren, wenn Ihr diese Apparatur benutzt! (4 Std. Abklingzeit)\nBenötigt Klassische Ingenieurskunst\n(260)\nBenötigt Gnomeningenieur" }
