entries[23509] = { ["name"] = "Frostwolfheuler", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Frostwolfheuler oder gibt ihn wieder frei.\n\"Wurde vom Frostwolfklan im Alteracgebirge aufgezogen.\"\nVerkäufer:\nJorek Eisenflanke\nZone:\nVorgebirge des Hügellands\nKosten:\n2000" }
