entries[23628] = { ["name"] = "Schwerer Gürtel der Holzschlundfeste", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (12), Essenz der Erde (3), Essenz des Lebens (3)\nVerkäufer:\nMeilosh\nZone:\nTeufelswald\nDie Holzschlundfeste - Wohlwollend\nKosten:\n2\n20\n\nSchwerer Gürtel der Holzschlundfeste\nWird beim Anlegen gebunden\nTaille Kette\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]+4 Ausdauer\nHaltbarkeit 50 / 50\n22" }
